using System;using System.IO;using System.IO.Compression;using System.Security.Cryptography;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Diagnostics;using System.Threading;using Microsoft.Win32;using System.Reflection;
static class InstallSupport{
 public const string Version="1.5.0";public const string Product="String Chat";public const string RegistryKey=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\StringChat";
 public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16000000};
 public static string DefaultRoot{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","StringChat");}}
 public static string LegacyRoot{get{return DefaultRoot;}}
 public static string Full(string path){return Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);}
 public static bool Inside(string root,string path){return !string.IsNullOrWhiteSpace(path)&&Full(path).StartsWith(Full(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
 public static void RequireInside(string root,string path){if(!Inside(root,path))throw new IOException("Destino fora da pasta do aplicativo.");}
 public static void NoLinks(string path){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("A pasta contém um redirecionamento. Nenhum arquivo foi removido.");if(Directory.Exists(path))foreach(string child in Directory.EnumerateFileSystemEntries(path))NoLinks(child);}
 public static void DeleteOwned(string root,string path){RequireInside(root,path);if(!Directory.Exists(path))return;NoLinks(path);Directory.Delete(path,true);}
 public static string Hex(byte[] bytes){return BitConverter.ToString(bytes).Replace("-","").ToLowerInvariant();}
 public sealed class IntegrationBackup{
  sealed class KeyState{public bool Exists;public Dictionary<string,Tuple<object,RegistryValueKind>> Values=new Dictionary<string,Tuple<object,RegistryValueKind>>();public Dictionary<string,KeyState> Children=new Dictionary<string,KeyState>();}
  Dictionary<string,KeyState> keys=new Dictionary<string,KeyState>();Dictionary<string,byte[]> shortcuts=new Dictionary<string,byte[]>();
  static KeyState Capture(RegistryKey key){var state=new KeyState{Exists=key!=null};if(key==null)return state;foreach(string name in key.GetValueNames())state.Values[name]=Tuple.Create(key.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames),key.GetValueKind(name));foreach(string name in key.GetSubKeyNames())using(var child=key.OpenSubKey(name))state.Children[name]=Capture(child);return state;}
  static void Write(RegistryKey key,KeyState state){foreach(var value in state.Values)key.SetValue(value.Key,value.Value.Item1,value.Value.Item2);foreach(var child in state.Children)using(var target=key.CreateSubKey(child.Key))Write(target,child.Value);}
  public IntegrationBackup(){foreach(string path in new[]{RegistryKey,@"Software\Classes\stringchat"})using(var key=Registry.CurrentUser.OpenSubKey(path))keys[path]=Capture(key);foreach(string directory in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Programs),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)})foreach(string name in new[]{"String Chat.lnk"}){string path=Path.Combine(directory,name);shortcuts[path]=File.Exists(path)?File.ReadAllBytes(path):null;}}
  public void Restore(){foreach(var state in keys){Registry.CurrentUser.DeleteSubKeyTree(state.Key,false);if(state.Value.Exists)using(var key=Registry.CurrentUser.CreateSubKey(state.Key))Write(key,state.Value);}foreach(var file in shortcuts){if(file.Value==null){if(File.Exists(file.Key))File.Delete(file.Key);}else File.WriteAllBytes(file.Key,file.Value);}}
 }
 public static string Hash(string path){using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))return Hex(sha.ComputeHash(stream));}
 public static void ValidatePackage(string directory){
  var manifest=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(directory,"package-manifest.json")));
  if((string)manifest["product"]!=Product||(string)manifest["version"]!=Version)throw new InvalidDataException("Pacote de outra versão.");
  var files=(System.Collections.IEnumerable)manifest["files"];int count=0;
  foreach(Dictionary<string,object> file in files){count++;string target=Full(Path.Combine(directory,(string)file["path"]));RequireInside(directory,target);if(Hash(target)!=(string)file["sha256"])throw new InvalidDataException("Arquivo incompleto: "+file["path"]);}if(count<10)throw new InvalidDataException("Pacote incompleto.");
  if(!File.Exists(Path.Combine(directory,"StringChat.exe"))||!File.Exists(Path.Combine(directory,"StringChatMaintenance.exe")))throw new InvalidDataException("Executável ausente.");
 }
 public static void VerifyExecutable(string directory){string profile=Path.Combine(directory,".verify-profile");var start=new ProcessStartInfo(Path.Combine(directory,"StringChat.exe"),"--verify-install --profile=\""+profile+"\""){WorkingDirectory=directory,UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};using(var process=Process.Start(start)){if(!process.WaitForExit(45000)){try{process.Kill();}catch{}throw new IOException("A verificação do programa demorou demais.");}if(process.ExitCode!=0)throw new IOException("O programa não passou na verificação. A versão anterior foi mantida.");}if(Directory.Exists(profile))DeleteOwned(directory,profile);}
 public static void Extract(Stream stream,string target,Action<int> progress){Directory.CreateDirectory(target);using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){int done=0;foreach(var entry in zip.Entries){string destination=Full(Path.Combine(target,entry.FullName));RequireInside(target,destination);if(entry.Name.Length==0)Directory.CreateDirectory(destination);else{Directory.CreateDirectory(Path.GetDirectoryName(destination));using(var input=entry.Open())using(var output=new FileStream(destination,FileMode.Create,FileAccess.Write,FileShare.None))input.CopyTo(output);}if(progress!=null)progress(++done*100/zip.Entries.Count);}}}
 public static bool IsVersion(string root,string path){
  try{RequireInside(root,path);System.Version version;if(!System.Version.TryParse(Path.GetFileName(path),out version))return false;NoLinks(path);string package=Path.Combine(path,"resources","app","package.json");var json=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(package));string name=(string)json["name"];return name=="string-chat-desktop"&&(string)json["version"]==Path.GetFileName(path)&&File.Exists(Path.Combine(path,"StringChat.exe"));}catch{return false;}
 }
 public static List<string> CleanupVersions(string root,string keep){var warnings=new List<string>();if(!Directory.Exists(root))return warnings;if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0){warnings.Add(root);return warnings;}foreach(string directory in Directory.GetDirectories(root)){if(string.Equals(Full(directory),Full(keep),StringComparison.OrdinalIgnoreCase)||!IsVersion(root,directory))continue;try{DeleteOwned(root,directory);}catch{warnings.Add(directory);}}return warnings;}
 public static void StopApps(string root){
  foreach(string name in new[]{"StringChat"})foreach(var process in Process.GetProcessesByName(name))using(process){try{string path=process.MainModule.FileName;if(!Inside(root,path)||process.Id==Process.GetCurrentProcess().Id)continue;try{process.CloseMainWindow();}catch{}if(!process.WaitForExit(2500)){var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"taskkill.exe"),"/PID "+process.Id+" /T /F"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};using(var kill=Process.Start(info))kill.WaitForExit(10000);process.WaitForExit(5000);}}catch{}}
 }
 public static string Current(string root){var state=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"current.json")));string version=(string)state["version"];System.Version parsed;if(!System.Version.TryParse(version,out parsed))throw new IOException("Versão inválida.");string target=Full(Path.Combine(root,version));RequireInside(root,target);if(!IsVersion(root,target))throw new IOException("Instalação não encontrada.");return target;}
 public static void Shortcut(string path,string root){Type type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type),link=null;try{link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{path});var t=link.GetType();t.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(root,"StringChat.exe")});t.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{root});t.InvokeMember("IconLocation",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(root,"StringChat.exe")+",0"});t.InvokeMember("Description",BindingFlags.SetProperty,null,link,new object[]{"String Chat — amigos, voz e tela"});t.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}finally{if(link!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
 public static void Register(string root,bool desktop){
  string programs=Environment.GetFolderPath(Environment.SpecialFolder.Programs),desktopDir=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
  Shortcut(Path.Combine(programs,"String Chat.lnk"),root);if(desktop)Shortcut(Path.Combine(desktopDir,"String Chat.lnk"),root);
  foreach(string old in new[]{Path.Combine(programs),Path.Combine(desktopDir)})if(File.Exists(old)){string previous=ShortcutTarget(old);if(Inside(root,previous)||Inside(LegacyRoot,previous))File.Delete(old);}
  foreach(string scheme in new[]{"stringchat"})using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Classes\"+scheme)){key.SetValue("","URL:String Chat");key.SetValue("URL Protocol","");using(var command=key.CreateSubKey(@"shell\open\command"))command.SetValue("","\""+Path.Combine(root,"StringChat.exe")+"\" \"%1\"");using(var icon=key.CreateSubKey("DefaultIcon"))icon.SetValue("",Path.Combine(root,"StringChat.exe")+",0");}
  using(var uninstall=Registry.CurrentUser.CreateSubKey(RegistryKey)){uninstall.SetValue("DisplayName",Product);uninstall.SetValue("DisplayVersion",Version);uninstall.SetValue("Publisher","String Chat");uninstall.SetValue("InstallLocation",root);uninstall.SetValue("DisplayIcon",Path.Combine(root,"StringChat.exe"));uninstall.SetValue("UninstallString","\""+Path.Combine(root,"StringChatMaintenance.exe")+"\" --uninstall");uninstall.SetValue("NoModify",1,RegistryValueKind.DWord);uninstall.SetValue("NoRepair",1,RegistryValueKind.DWord);}
 }
 public static void RemoveIntegrations(string root){
  foreach(string scheme in new[]{"stringchat"})using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Classes\"+scheme+@"\shell\open\command")){if(key!=null&&Convert.ToString(key.GetValue("")).Contains(Path.Combine(root,"StringChat.exe")))Registry.CurrentUser.DeleteSubKeyTree(@"Software\Classes\"+scheme,false);}
  using(var key=Registry.CurrentUser.OpenSubKey(RegistryKey)){if(key!=null&&string.Equals(Convert.ToString(key.GetValue("InstallLocation")),root,StringComparison.OrdinalIgnoreCase))Registry.CurrentUser.DeleteSubKeyTree(RegistryKey,false);}
  foreach(string directory in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Programs),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)})foreach(string name in new[]{"String Chat.lnk"}){string file=Path.Combine(directory,name);if(!File.Exists(file))continue;Type type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type),link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{file});try{string target=Convert.ToString(link.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,link,null));if(Inside(root,target))File.Delete(file);}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
 }
 public static string ShortcutTarget(string path){Type type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type),link=null;try{link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{path});return Convert.ToString(link.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,link,null));}finally{if(link!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
}
